"use client";

/**
 * Comment pile: comment cards land under a launch post, slowly at first and
 * then faster, until they fill the frame. The pile then dims and one comment
 * lifts out of it. The "people are talking" beat of a launch film.
 *
 * Written by Better Design. Painted from the theme prop.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, random, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const COLS = 3;
const FIRST_AT = 14;
/** Frames from the first comment to the last. Arrivals bunch up towards the end. */
const PILE_FRAMES = 70;
const LAND_FRAMES = 14;
const FOCUS_AT = 104;
const FOCUS_FRAMES = 18;

export interface CommentPileProps {
  /** Each entry reads "Name: comment". Twelve fill the frame. */
  comments?: string[];
  /** The launch post the comments sit under. */
  headline?: string;
  /** Who posted it. */
  author?: string;
  /** Index in `comments` of the one that lifts out at the end. */
  highlight?: number;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const DEFAULT_COMMENTS = [
  "Maya L.: This is exactly what our team needed.",
  "Jonas K.: Set it up in five minutes. Wow.",
  "Priya S.: The onboarding is so calm.",
  "Leo M.: Congrats on the launch!",
  "Ines R.: Finally, someone got this right.",
  "Sam T.: Bookmarked and shared with the team.",
  "Noor A.: The details here are lovely.",
  "Theo B.: Switching over this week.",
  "Hana W.: Clean, fast and obvious. Love it.",
  "Omar D.: How long did this take to build?",
  "Lena F.: Our designers will be thrilled.",
  "Ravi P.: Instant upvote from me.",
];

const split = (entry: string): [string, string] => {
  const at = entry.indexOf(":");
  return at < 0 ? ["Someone", entry.trim()] : [entry.slice(0, at).trim(), entry.slice(at + 1).trim()];
};

const initials = (name: string): string =>
  name.split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]?.toUpperCase() ?? "").join("");

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** A launch post whose comment section fills up, then one comment is singled out. */
export function CommentPile({
  comments = DEFAULT_COMMENTS,
  headline = "Your product is live today",
  author = "Your team",
  highlight = 4,
  theme: themeOverride,
  font,
}: CommentPileProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const list = comments.slice(0, 12);
  const n = Math.max(list.length, 1);
  const pick = Math.min(Math.max(highlight, 0), n - 1);

  const postT = easings.out(interpolate(frame, [0, 16], [0, 1], clamp));
  const focus = easings.inOut(interpolate(frame, [FOCUS_AT, FOCUS_AT + FOCUS_FRAMES], [0, 1], clamp));
  const shown = list.filter((_, i) => frame >= FIRST_AT + PILE_FRAMES * Math.sqrt(i / n)).length;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, padding: "88px 120px", gap: 36 }}>
      <div
        style={{
          display: "flex", alignItems: "center", gap: 28, padding: "28px 36px", borderRadius: theme.radius * 2,
          background: theme.card, border: `1px solid ${theme.border}`,
          opacity: postT, transform: `translateY(${(1 - postT) * 24}px)`,
        }}
      >
        <div style={{ width: 88, height: 88, borderRadius: theme.radius * 1.6, background: theme.primary, color: theme.primaryForeground, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 36, fontWeight: 700 }}>
          {initials(author)}
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 6, flex: 1 }}>
          <div style={{ fontSize: 26, fontWeight: 500, color: theme.mutedForeground }}>{author}</div>
          <div style={{ fontSize: 48, fontWeight: 700, letterSpacing: "-0.02em", color: theme.foreground }}>{headline}</div>
        </div>
        <div style={{ fontSize: 28, fontWeight: 600, color: theme.mutedForeground, fontVariantNumeric: "tabular-nums" }}>
          {`${shown} ${shown === 1 ? "comment" : "comments"}`}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: `repeat(${COLS}, 1fr)`, gridAutoRows: "1fr", gap: 22, flex: 1 }}>
        {list.map((entry, i) => {
          const [name, text] = split(entry);
          const at = FIRST_AT + PILE_FRAMES * Math.sqrt(i / n);
          const t = easings.out(interpolate(frame, [at, at + LAND_FRAMES], [0, 1], clamp));
          const tilt = (random(`tilt-${i}`) - 0.5) * 7 * (1 - t);
          const isPick = i === pick;
          const dim = isPick ? 1 : 1 - focus * 0.62;
          const lift = isPick ? focus : 0;
          return (
            <div
              key={i}
              style={{
                position: "relative", zIndex: isPick ? 2 : 1,
                display: "flex", gap: 20, alignItems: "center", padding: "24px 28px", borderRadius: theme.radius * 1.6,
                background: theme.card,
                border: `${isPick ? 2 : 1}px solid ${isPick ? withAlpha(theme.primary, focus) : theme.border}`,
                boxShadow: `0 ${8 + lift * 22}px ${24 + lift * 40}px oklch(0 0 0 / ${0.05 + lift * 0.12})`,
                opacity: t * dim,
                transform: `translateY(${(1 - t) * 60 - lift * 10}px) rotate(${tilt}deg) scale(${(0.94 + 0.06 * t) * (1 + lift * 0.06)})`,
              }}
            >
              <div style={{ flexShrink: 0, width: 56, height: 56, borderRadius: 28, background: withAlpha(theme.primary, 0.12 + 0.08 * (i % 3)), color: theme.primary, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22, fontWeight: 700 }}>
                {initials(name)}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6, minWidth: 0 }}>
                <div style={{ fontSize: 24, fontWeight: 600, color: theme.foreground }}>{name}</div>
                <div style={{ fontSize: 26, fontWeight: 500, lineHeight: 1.3, color: isPick ? theme.foreground : theme.mutedForeground }}>{text}</div>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}
